CREATE FUNCTION security.fn_rep_filter(@rep_login AS sysname)
    RETURNS TABLE WITH SCHEMABINDING
AS RETURN SELECT 1 AS allowed WHERE @rep_login = USER_NAME();
GO
CREATE SECURITY POLICY security.sales_by_rep
    ADD FILTER PREDICATE security.fn_rep_filter(rep_login) ON dbo.sales
    WITH (STATE = ON);
GO
ALTER TABLE dbo.customers
    ALTER COLUMN email ADD MASKED WITH (FUNCTION = 'email()');
